// One normalized request for Telegram and the private n8n test chat.
const incoming = $input.first().json;
const message = incoming.message;
const isTelegram = message?.chat?.id !== undefined;
if (isTelegram && message.from?.is_bot) return [];
const source = isTelegram ? 'telegram' : 'chat';
const chatId = isTelegram ? String(message.chat.id) : '';
const threadId = isTelegram ? (message.message_thread_id ?? null) : null;
const senderId = isTelegram ? String(message.from?.id ?? chatId) : '';
let chatInput = String(isTelegram ? (message.text ?? message.caption ?? '') : (incoming.chatInput ?? '')).trim();
const originalInput = chatInput;
const sessionId = isTelegram ? `ultimate:telegram:${chatId}:${threadId ?? 0}:${senderId}`
  : `ultimate:chat:${String(incoming.sessionId ?? $execution.id)}`;
const norm = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const aliases = {
  tous: 'tous', tout: 'tous', globale: 'tous', globales: 'tous',
  livre: 'livres', livres: 'livres', lecture: 'livres', ouvrage: 'livres', ouvrages: 'livres',
  roman: 'romans', romans: 'romans', bd: 'bd', manga: 'mangas', mangas: 'mangas', comic: 'comics', comics: 'comics',
  audio: 'audio', audible: 'audio', 'livre audio': 'audio', 'livres audio': 'audio',
  'bandes dessinees': 'bd', 'bande dessinee': 'bd',
  film: 'films', films: 'films', serie: 'series', series: 'series', episode: 'series', episodes: 'series',
  jv: 'jeux_video', 'jeu video': 'jeux_video', 'jeux video': 'jeux_video', 'jeux videos': 'jeux_video',
  jds: 'jeux_societe', 'jeu de societe': 'jeux_societe', 'jeux de societe': 'jeux_societe',
  musique: 'musique', musiques: 'musique', morceau: 'musique', morceaux: 'musique',
  chanson: 'musique', chansons: 'musique', 'fichier audio': 'musique', 'fichiers audio': 'musique',
};
const match = chatInput.match(/^\/([a-z]+)(?:@\w+)?(?:\s+([\s\S]*))?$/i);
const command = (match?.[1] ?? '').toLowerCase();
const argument = (match?.[2] ?? '').trim();
let route = 'agent';
let focus = '';
let output = '';
const question = norm(chatInput)
  .replace(/^(?:bonjour|bonsoir|salut)\s+/, '')
  .replace(/^(?:(?:est ce que )?tu peux|peux tu|pourrais tu)\s+(?:me\s+)?/, '')
  .replace(/^(?:dire|donner|indiquer|dis moi|donne moi|indique moi|affiche(?: moi)?)\s+/, '')
  .replace(/^(?:au total|en tout)\s+/, '')
  .replace(/\s+(?:s il te plait|s il vous plait|svp|stp|merci)$/, '').trim();
const noun = '(?<noun>livres? audio|fichiers? audio|jeux? de societe|jeux? videos?|bandes? dessinees?|livres?|ouvrages?|romans?|mangas?|comics?|bd|films?|series?|episodes?|musiques?|morceaux?|chansons?)';
const owner = '(?:ai je|j ai|je possede|que j ai|que je possede|est ce que j ai|est ce que je possede)';
const place = '(?:dans (?:ma|la) (?:bibliotheque|collection|ludotheque)(?: musicale| de musiques?)?|dans (?:mon|le) dossier(?: (?:de )?musiques?)?|sur (?:mon |le )?(?:google )?drive)';
const suffix = `(?: (?:au total|en tout))?(?: ${place})?(?: (?:au total|en tout))?`;
const patterns = [
  `(?:j ai|je possede) combien de ${noun}`,
  `combien de ${noun}(?: ${owner})?`,
  `combien ${owner} de ${noun}`,
  `combien (?:y a t il|il y a) de ${noun}`,
  `il y a combien de ${noun}`,
  `(?:quel est |c est quoi )?(?:le |mon )?(?:nombre(?: total)?|total) (?:de |de mes |des )${noun}(?: ${owner})?`,
  `(?:compte|compter|denombre|denombrer) (?:mes|les|(?:tous|toutes) (?:mes|les)) ${noun}(?: ${owner})?`,
];
if (!command) for (const pattern of patterns) {
  const found = question.match(new RegExp(`^(?:${pattern})${suffix}$`));
  if (found) { route = 'stats'; focus = aliases[found.groups.noun] ?? 'tous'; break; }
}
if (!command && /^(?:mes statistiques|(?:les )?statistiques(?: globales| de ma collection)?)$/.test(question)) { route = 'stats'; focus = 'tous'; }
if (['stats', 'total'].includes(command)) {
  route = 'stats'; focus = argument ? aliases[norm(argument)] : 'tous';
  if (!focus) output = 'Thème inconnu. Exemples : /stats, /stats livres, /stats audio, /stats musique, /stats films, /stats series, /stats jv, /stats jds.';
} else if (['tomes', 'serie'].includes(command)) {
  route = 'tomes'; focus = 'livres';
  if (!argument) output = 'Indique une série de BD ou manga : /tomes Toriko. Pour la télévision : /series suivi de ta question.';
} else if (command === 'chercher') {
  route = 'chercher';
  if (!argument) output = 'Indique un titre : /chercher Dune. Cette commande cherche dans les sept tables ; pour la musique, écris ta question normalement.';
} else if (['livres', 'audio', 'musique', 'films', 'series', 'jv', 'jds'].includes(command)) {
  focus = aliases[command];
  if (!argument) output = 'Ajoute ta question après la commande, ou utilise /stats suivi du thème.';
  else chatInput = `Thème : ${focus}. Question : ${argument}`;
} else if (['help', 'start'].includes(command)) {
  output = 'Je peux te conseiller sur tes livres (BD, romans et audio), musiques, films, séries, jeux vidéo et jeux de société.\n\n'
    + '• /stats : bilan des six thèmes\n• /stats livres, /stats audio, /stats musique\n'
    + '• /stats films, /stats series, /stats jv, /stats jds\n'
    + '• /tomes Toriko : compteurs d’une série de BD/manga\n• /chercher Dune : recherche dans les tables\n\n'
    + 'Tu peux écrire naturellement : « J’ai combien de musique ? », « Conseille-moi un livre audio que je possède », '
    + '« Propose un film à voir » ou « À quel jeu de société de ma collection jouer ? ».\n'
    + 'Pour les tomes manquants, les tables contiennent des quantités, pas les numéros précis.';
} else if (command) output = 'Commande inconnue. Utilise /help ou écris ta question normalement.';
if (!originalInput) output = 'Envoie-moi un message écrit. La transcription des messages vocaux n’est pas configurée.';
// Skip table reads only for an explicit or unambiguous music-only request.
if (!focus && /\b(?:musique|musiques|morceau|morceaux|chanson|chansons|playlist)\b/.test(question)
  && !/\b(?:livre|livres|audio|audible|roman|romans|bd|manga|mangas|comic|comics|film|films|serie|series|episode|episodes|jeu|jeux|lecture)\b/.test(question)) focus = 'musique';
return [{ json: {
  source, chatId, threadId, sessionId, chatInput, originalInput, command, argument, route, focus,
  needsWork: !output, needsCatalog: !output && focus !== 'musique',
  countMusic: !output && route === 'stats' && ['tous', 'musique'].includes(focus), output,
} }];

// Normalize all seven tables once. Catalog data stays outside model prompts.
const clean = value => String(value ?? '').replace(/\s+/g, ' ').trim();
const norm = value => clean(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const unique = values => [...new Set(values.filter(value => value !== null && value !== ''))];
const ownedStatus = value => /^possede(?:e|s)?(?:\s|$)/.test(norm(value));
const number = value => {
  const text = clean(value).replace(/[\s\u00a0\u202f]/g, '').replace(',', '.');
  if (!/^\d+(?:\.\d+)?$/.test(text)) return null;
  const result = Number(text);
  return Number.isFinite(result) && result >= 0 ? result : null;
};
const integer = value => {
  const result = number(value);
  return Number.isSafeInteger(result) ? result : null;
};
const boolean = value => ['1', 'true', 'oui', 'yes'].includes(norm(value)) ? true
  : ['0', 'false', 'non', 'no'].includes(norm(value)) ? false : null;
const duration = value => {
  const match = norm(value).match(/^(?:(\d+)\s*h(?:eures?)?\s*)?(?:(\d+)\s*min(?:utes?)?)?$/);
  return match && (match[1] || match[2]) ? Number(match[1] || 0) * 60 + Number(match[2] || 0) : null;
};
const categoryFor = value => {
  const category = norm(value);
  return /manga/.test(category) ? 'mangas' : /comic/.test(category) ? 'comics'
    : /^(?:bd|bandes? dessinees?|franco belge)$/.test(category) ? 'bd'
    : /^autres?$/.test(category) ? 'autres' : 'non_classes';
};
const catalog = [];
const sources = {};
const specs = [
  ['bd', 'Read BD', 'titre', 'id_unique'], ['roman', 'Read Roman', 'titre', 'id_unique'],
  ['audio', 'Read Audible', 'titre', 'id_unique'], ['film', 'Read Film', 'movie_name', 'movie_uuid'],
  ['serie', 'Read Serie', 'series_name', 'series_uuid'], ['jeu_video', 'Read Jeux video', 'titre', null],
  ['jeu_societe', 'Read Jeux de societe', 'Nom', null],
];
for (const [support, node, titleField, keyField] of specs) {
  const items = $(node).all();
  const source = { available: true, rows: 0, records: 0, repeatedRows: 0, invalidRows: 0, conflicts: 0, missingIds: 0 };
  sources[support] = source;
  if (items.some(item => item.error || item.json?.error || (Object.hasOwn(item.json ?? {}, 'chatInput') && !Object.hasOwn(item.json ?? {}, titleField)))) {
    source.available = false;
    source.error = `La table ${node.replace(/^Read /, '')} n’a pas pu être lue.`;
    continue;
  }
  const groups = new Map();
  for (const item of items) {
    const row = item.json ?? {};
    if (!Object.keys(row).length) continue;
    if (!clean(row[titleField])) { source.invalidRows++; continue; }
    source.rows++;
    let id = keyField ? clean(row[keyField]) : '';
    if (!id) {
      if (keyField) source.missingIds++;
      id = norm(row[titleField]) + (support === 'jeu_societe' ? `|${norm(row.categorie)}` : '')
        + (support === 'roman' || support === 'audio' ? `|${norm(row.auteur)}` : '');
    }
    if (!groups.has(id)) groups.set(id, []);
    else source.repeatedRows++;
    groups.get(id).push(row);
  }
  source.records = groups.size;
  for (const [id, rows] of groups) {
    const states = unique(rows.map(row => clean(row.statut ?? row.Statut ?? row.statuts)));
    const ownedRows = rows.filter(row => ownedStatus(row.statut));
    const preferred = ownedRows[0] ?? rows[0];
    const record = { id, support, titre: clean(preferred[titleField]).slice(0, 320),
      statuts: states, anomalies: [] };
    const counter = (field, parser = integer) => {
      const raw = rows.map(row => row[field]).filter(value => clean(value) !== '');
      const values = unique(raw.map(parser));
      if (values.length > 1 || raw.some(value => parser(value) === null)) {
        source.conflicts++;
        record.anomalies.push(`Valeurs contradictoires ou invalides : ${field}.`);
        return null;
      }
      return values.length ? values[0] : null;
    };
    const reading = row => /\bnon lu\b/.test(norm(row.statut)) ? 'non_lu'
      : /\bje lis\b/.test(norm(row.statut)) ? 'en_cours'
      : /\blu\b/.test(norm(row.statut)) ? 'lu' : 'inconnu';
    if (['bd', 'roman', 'audio'].includes(support)) {
      record.possession = ownedRows.length ? true : null;
      record.souhait = false;
      if (support === 'bd') {
        const categories = unique(rows.map(row => clean(row.categorie)));
        record.categorie = categories.length === 1 ? categoryFor(categories[0]) : 'non_classes';
        for (const field of ['albums_possedes', 'albums_lus', 'albums_manquants', 'albums_non_possedes_lu']) record[field] = counter(field);
        if (record.albums_possedes !== null) record.possession = record.albums_possedes > 0;
        record.lecture = record.albums_lus === null ? 'inconnu' : record.albums_lus === 0 ? 'non_lu'
          : record.albums_possedes !== null && record.albums_lus >= record.albums_possedes ? 'lu' : 'en_cours';
        if (ownedRows.length && record.albums_possedes === null) record.anomalies.push('Nombre de tomes possédés inconnu.');
      } else {
        record.possession = ownedRows.length > 0;
        record.auteur = unique(rows.map(row => clean(row.auteur))).join(' / ').slice(0, 260);
        record.genre = unique(rows.map(row => clean(row.genre))).join(' / ').slice(0, 260);
        record.categorie = support === 'audio' ? 'livres_audio' : 'romans';
        if (support === 'audio') {
          record.duree_minutes = counter('duree_brute', duration);
          record.ecoute = states.some(state => ownedStatus(state) && /\becoute\b/.test(norm(state)));
          record.lecture = record.ecoute ? 'ecoute' : record.possession ? 'non_marque_ecoute' : 'inconnu';
        } else {
          const readings = unique((ownedRows.length ? ownedRows : rows).map(reading));
          record.lecture = readings.length === 1 ? readings[0] : 'statuts_mixtes';
          record.editions_regroupees = unique(rows.map(row => [clean(row.editeur), clean(row.annee_sortie), clean(row.nb_pages)].join('|'))).length;
        }
      }
      record.souhait = record.possession !== true && states.some(state => /souhait/.test(norm(state)));
    } else if (support === 'film') {
      record.vu = states.some(state => norm(state) === 'vu');
      record.a_voir = !record.vu && states.some(state => ['watchlist', 'a voir'].includes(norm(state)));
      record.duree_minutes = counter('runtime_minutes');
    } else if (support === 'serie') {
      record.episodes_vus = counter('episodes_seen_count');
      record.episodes_restants = counter('episodes_remaining_count');
      record.a_jour = states.some(state => norm(state) === 'a jour');
      record.en_cours = states.some(state => /en cours/.test(norm(state))) && !record.a_jour;
      record.a_voir = !record.en_cours && !record.a_jour && states.some(state => ['watchlist', 'a voir'].includes(norm(state)));
      record.dernier_episode = unique(rows.map(row => clean(row.last_episode_title))).join(' / ').slice(0, 200);
    } else if (support === 'jeu_video') {
      const anyFlag = field => {
        const values = rows.map(row => boolean(row[field])).filter(value => value !== null);
        return values.includes(true) ? true : values.length ? false : null;
      };
      record.dans_ludotheque = anyFlag('dans_ludotheque');
      record.souhait = anyFlag('liste_souhait');
      record.coup_de_coeur = anyFlag('coup_de_coeur');
      record.complete_100_pourcent = anyFlag('complete_100_pourcent');
      record.note = counter('note', number);
      const categories = unique(states.map(norm));
      record.etat_jeu = categories.length === 1 ? categories[0] : 'statuts mixtes';
    } else {
      const statesSet = new Set(states.flatMap(state => norm(state).split(' ')));
      record.dans_collection = states.length ? statesSet.has('collection') : null;
      record.souhait = statesSet.has('wishlist') || statesSet.has('souhait');
      const categories = unique(rows.map(row => norm(row.categorie)));
      record.categorie = categories.length === 1 ? categories[0] : 'non classe';
      record.jeu_complet = ['jeu de base', 'standalone'].includes(record.categorie);
      record.genre = unique(rows.map(row => clean(row.genre))).join(' / ').slice(0, 250);
      record.prix = counter('prix', number);
      record.annee_sortie = counter('annee_sortie');
    }
    if (Object.hasOwn(record, 'duree_minutes') && !(record.duree_minutes > 0)) record.duree_minutes = null;
    record.searchTitle = norm(record.titre);
    record.searchKey = norm([record.titre, record.auteur, record.genre, record.categorie].filter(Boolean).join(' '));
    catalog.push(record);
  }
}
catalog.sort((a, b) => a.titre.localeCompare(b.titre, 'fr') || a.support.localeCompare(b.support));
return [{ json: { kind: 'catalog', catalog, sources } }];

const items = $input.all();
if (items.some(item => item.error || item.json?.error)) return [{ json: { kind: 'music', statut: 'indisponible', total: null } }];
const ids = new Set();
for (const item of items) {
  const row = item.json;
  if (typeof row.id === 'string' && String(row.mimeType ?? '').startsWith('audio/') && !row.trashed) ids.add(row.id);
}
return [{ json: { kind: 'music', statut: 'ok', total: ids.size } }];

// Shared pure functions, embedded in deterministic branches and bounded AI tools.
const THEMES = {
  livres: ['bd', 'roman', 'audio'], films: ['film'], series: ['serie'],
  jeux_video: ['jeu_video'], jeux_societe: ['jeu_societe'],
};
const normalizeText = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const sumKnown = (rows, field) => rows.some(row => row[field] === null || row[field] === undefined)
  ? null : rows.reduce((sum, row) => sum + row[field], 0);
const countIf = (rows, predicate) => rows.filter(predicate).length;
const formatted = value => value === null || value === undefined ? 'non renseigné' : value.toLocaleString('fr-FR');
const formattedDuration = value => value === null || value === undefined ? 'non renseignée' : `${Math.floor(value / 60)} h ${value % 60} min`;

function statistics(library, theme = 'tous') {
  if (theme === 'musique') return { statut: library.music.statut, fichiers_audio: library.music.total ?? null,
    portee: 'Fichiers identifiés audio directement dans Dossier Musiques ; copies distinctes comptées séparément, sous-dossiers exclus.' };
  const selected = theme === 'tous' ? Object.keys(library.sources) : THEMES[theme];
  if (!selected) return { statut: 'parametre_invalide', message: 'Thème inconnu.' };
  const unavailable = selected.filter(key => !library.sources[key]?.available);
  const invalidRows = selected.reduce((sum, key) => sum + (library.sources[key]?.invalidRows ?? 0), 0);
  const result = { statut: unavailable.length || invalidRows ? 'partiel' : 'ok',
    sources_indisponibles: unavailable, lignes_invalides: invalidRows,
    doublons_regroupes: selected.reduce((sum, key) => sum + (library.sources[key]?.repeatedRows ?? 0), 0) };
  if (theme === 'tous') {
    for (const name of Object.keys(THEMES)) result[name] = statistics(library, name);
    result.musique = statistics(library, 'musique');
    if (Object.keys(THEMES).some(name => result[name].statut !== 'ok') || result.musique.statut !== 'ok') result.statut = 'partiel';
    result.remarque = 'Les thèmes utilisent des unités différentes : aucun total mélangeant livres, films, épisodes et jeux.';
    return result;
  }
  const records = library.catalog.filter(row => selected.includes(row.support));
  if (theme === 'livres') {
    const bd = records.filter(row => row.support === 'bd');
    const ownedBd = bd.filter(row => row.possession === true);
    const badOwned = bd.some(row => row.anomalies.some(text => /albums_possedes|tomes possédés inconnu/.test(text)));
    const albums = {};
    for (const category of ['mangas', 'comics', 'bd', 'autres', 'non_classes']) {
      const unknown = bd.some(row => row.categorie === category && row.anomalies.some(text => /albums_possedes|tomes possédés inconnu/.test(text)));
      albums[category] = unknown ? null : sumKnown(ownedBd.filter(row => row.categorie === category), 'albums_possedes');
    }
    const romans = records.filter(row => row.support === 'roman');
    const audio = records.filter(row => row.support === 'audio');
    const ownedRomans = romans.filter(row => row.possession);
    const ownedAudio = audio.filter(row => row.possession);
    const totalAlbums = badOwned ? null : sumKnown(ownedBd, 'albums_possedes');
    const available = key => library.sources[key]?.available && !library.sources[key].invalidRows;
    result.albums = available('bd') ? { ...albums, total: totalAlbums,
      series_possedees: ownedBd.length, tomes_manquants_series_possedees: sumKnown(ownedBd, 'albums_manquants') } : null;
    result.romans = available('roman') ? { possedes: ownedRomans.length,
      lus: countIf(ownedRomans, row => row.lecture === 'lu'), non_lus: countIf(ownedRomans, row => row.lecture === 'non_lu'),
      en_cours: countIf(ownedRomans, row => row.lecture === 'en_cours'), souhaits: countIf(romans, row => row.souhait) } : null;
    result.livres_audio = available('audio') ? { possedes: ownedAudio.length,
      ecoutes: countIf(ownedAudio, row => row.ecoute), non_marques_ecoutes: countIf(ownedAudio, row => !row.ecoute),
      souhaits: countIf(audio, row => row.souhait), duree_possedee_minutes: sumKnown(ownedAudio, 'duree_minutes'),
      duree_possedee_connue_minutes: ownedAudio.reduce((sum, row) => sum + (row.duree_minutes ?? 0), 0),
      titres_duree_inconnue: countIf(ownedAudio, row => row.duree_minutes === null),
      duree_titres_marques_ecoutes_minutes: sumKnown(ownedAudio.filter(row => row.ecoute), 'duree_minutes') } : null;
    result.total_livres_possedes = result.statut === 'ok' && totalAlbums !== null ? totalAlbums + ownedRomans.length + ownedAudio.length : null;
    if (totalAlbums === null) result.statut = 'partiel';
    result.portee = 'Albums BD + titres distincts Roman + titres audio distincts. Papier et audio sont deux supports séparés. Les éditions portant le même id_unique sont regroupées dans chaque table. La durée écoutée est la durée intégrale des titres marqués écoutés, pas un suivi des écoutes partielles.';
  } else if (theme === 'films') {
    result.films = unavailable.length || invalidRows ? null : { total_references: records.length,
      vus: countIf(records, row => row.vu), a_voir: countIf(records, row => row.a_voir),
      duree_films_vus_minutes: sumKnown(records.filter(row => row.vu), 'duree_minutes'),
      statuts_non_classes: countIf(records, row => !row.vu && !row.a_voir) };
    result.portee = 'Titres distincts dans Trakt ; un film Vu est compté une fois, pas une fois par visionnage. Aucune information de possession DVD.';
  } else if (theme === 'series') {
    const started = records.filter(row => row.en_cours || row.a_jour);
    result.series = unavailable.length || invalidRows ? null : { total_references: records.length,
      a_voir: countIf(records, row => row.a_voir), en_cours: countIf(records, row => row.en_cours),
      a_jour: countIf(records, row => row.a_jour), episodes_vus: sumKnown(records, 'episodes_vus'),
      episodes_restants_series_commencees: sumKnown(started, 'episodes_restants'),
      statuts_non_classes: countIf(records, row => !row.a_voir && !row.en_cours && !row.a_jour) };
    result.portee = 'À jour signifie aucun épisode restant selon la table, pas que la production de la série est terminée. Les épisodes futurs non renseignés ne sont pas connus.';
  } else if (theme === 'jeux_video') {
    const owned = records.filter(row => row.dans_ludotheque);
    result.jeux_video = unavailable.length || invalidRows ? null : { dans_ludotheque: owned.length,
      souhaits: countIf(records, row => row.souhait), termines: countIf(owned, row => row.etat_jeu === 'termine'),
      a_jouer: countIf(owned, row => row.etat_jeu === 'a jouer'), en_cours: countIf(owned, row => row.etat_jeu === 'en cours'),
      abandonnes: countIf(owned, row => row.etat_jeu === 'abandonne'),
      coups_de_coeur: countIf(owned, row => row.coup_de_coeur), completes_100_pourcent: countIf(owned, row => row.complete_100_pourcent) };
    result.portee = 'Jeux distincts par titre. Aucune plateforme, durée de jeu ou fonctionnalité coop n’est présente dans cette table.';
  } else {
    const owned = records.filter(row => row.dans_collection);
    result.jeux_societe = unavailable.length || invalidRows ? null : { articles_collection: owned.length,
      jeux_complets: countIf(owned, row => row.jeu_complet), jeux_de_base: countIf(owned, row => row.categorie === 'jeu de base'),
      standalone: countIf(owned, row => row.categorie === 'standalone'), extensions: countIf(owned, row => row.categorie === 'extension'),
      accessoires: countIf(owned, row => row.categorie === 'accessoire'), goodies: countIf(owned, row => row.categorie === 'goodie'),
      non_classes: countIf(owned, row => !['jeu de base', 'standalone', 'extension', 'accessoire', 'goodie'].includes(row.categorie)),
      souhaits: countIf(records, row => row.souhait),
      valeur_collection_connue_euros: owned.reduce((sum, row) => sum + Math.round((row.prix ?? 0) * 100), 0) / 100,
      prix_inconnus: countIf(owned, row => row.prix === null) };
    result.portee = 'Articles regroupés par nom et catégorie. Jeux complets = jeux de base + standalone, avec les puzzles classés comme jeux de base. Les prix viennent de la table. Nombre de joueurs et durée de partie non renseignés.';
  }
  return result;
}

function formatStatistics(library, theme = 'tous') {
  const stats = statistics(library, theme);
  if (theme === 'tous') return Object.keys(THEMES).map(name => formatStatistics(library, name)).join('\n\n') + '\n\n' + formatStatistics(library, 'musique');
  if (theme === 'musique') return stats.statut === 'ok'
    ? `Musique : ${formatted(stats.fichiers_audio)} fichiers audio directement dans le dossier configuré. Les copies distinctes comptent séparément.`
    : stats.statut === 'non_demande' ? 'Musique : utilise /stats musique pour lancer le comptage complet dans Drive.'
      : 'Musique : le comptage Drive est indisponible. Vérifie le compte et le dossier configurés.';
  const parts = [];
  if (theme === 'livres') {
    parts.push(`Livres — total enregistré comme possédé : ${formatted(stats.total_livres_possedes)}.`);
    if (stats.albums) parts.push(`Mangas : ${formatted(stats.albums.mangas)} ; comics : ${formatted(stats.albums.comics)} ; BD franco-belges : ${formatted(stats.albums.bd)} ; autres : ${formatted(stats.albums.autres)}${stats.albums.non_classes ? ` ; non classés : ${stats.albums.non_classes}` : ''}.`);
    if (stats.romans) parts.push(`Romans : ${stats.romans.possedes} possédés (${stats.romans.lus} lus, ${stats.romans.non_lus} non lus, ${stats.romans.en_cours} en cours) ; ${stats.romans.souhaits} en souhait.`);
    if (stats.livres_audio) parts.push(`Livres audio : ${stats.livres_audio.possedes} possédés, dont ${stats.livres_audio.ecoutes} marqués écoutés ; ${stats.livres_audio.souhaits} en souhait. Durée renseignée : ${formattedDuration(stats.livres_audio.duree_possedee_connue_minutes)}${stats.livres_audio.titres_duree_inconnue ? ` (${stats.livres_audio.titres_duree_inconnue} titre(s) sans durée connue)` : ''}.`);
    parts.push('Papier et audio comptent séparément ; les identifiants répétés sont regroupés dans chaque table.');
  } else if (theme === 'films' && stats.films) {
    parts.push(`Films — ${stats.films.vus} vus ; ${stats.films.a_voir} à voir ; ${stats.films.total_references} références au total.`);
  } else if (theme === 'series' && stats.series) {
    parts.push(`Séries — ${stats.series.en_cours} en cours ; ${stats.series.a_jour} à jour ; ${stats.series.a_voir} à voir.`,
      `Épisodes vus : ${formatted(stats.series.episodes_vus)}. Restants dans les séries commencées : ${formatted(stats.series.episodes_restants_series_commencees)}.`,
      'Une série à jour peut encore avoir de futurs épisodes.');
  } else if (theme === 'jeux_video' && stats.jeux_video) {
    const v = stats.jeux_video;
    parts.push(`Jeux vidéo — ${v.dans_ludotheque} dans la ludothèque ; ${v.souhaits} en souhait.`,
      `${v.termines} terminés ; ${v.a_jouer} à jouer ; ${v.en_cours} en cours ; ${v.abandonnes} abandonnés.`);
  } else if (theme === 'jeux_societe' && stats.jeux_societe) {
    const b = stats.jeux_societe;
    parts.push(`Jeux de société — ${b.jeux_complets} jeux complets (${b.jeux_de_base} jeux de base et ${b.standalone} standalone).`,
      `La collection contient ${b.articles_collection} articles au total, dont ${b.extensions} extensions, ${b.accessoires} accessoires et ${b.goodies} goodies${b.non_classes ? ` ; ${b.non_classes} non classés` : ''}. Souhaits : ${b.souhaits}.`);
  }
  if (stats.statut !== 'ok') parts.push(`Données incomplètes pour ce thème${stats.sources_indisponibles.length ? ` : ${stats.sources_indisponibles.join(', ')}` : ' : certaines lignes ou quantités sont à vérifier'}. Aucun total inconnu n’est remplacé par zéro.`);
  return parts.join('\n');
}

function bookPurchaseChecks(library) {
  // Match identical normalized titles conservatively, without merging record identities or totals.
  const titles = new Map();
  const owned = row => row.possession === true || row.albums_possedes > 0
    || row.statuts.some(status => /^possede(?:e|s)?(?:\s|$)/.test(normalizeText(status)));
  const read = row => row.ecoute === true || ['lu', 'ecoute', 'en_cours'].includes(row.lecture)
    || row.albums_lus > 0 || row.albums_non_possedes_lu > 0
    || row.statuts.some(status => {
      const value = normalizeText(status);
      return !/\bnon lu\b/.test(value) && /\blu\b|\bje lis\b/.test(value);
    });
  for (const row of library.catalog) {
    if (!THEMES.livres.includes(row.support)) continue;
    if (!titles.has(row.searchTitle)) titles.set(row.searchTitle, []);
    titles.get(row.searchTitle).push(row);
  }
  const checks = new Map();
  for (const rows of titles.values()) {
    const ownedAnywhere = rows.some(owned);
    const readAnywhere = rows.some(read);
    for (const row of rows) {
      const sameSupport = rows.filter(other => other.support === row.support);
      const ownedHere = sameSupport.some(owned);
      const explicitUnowned = row.albums_possedes === 0
        || row.statuts.some(status => /^non possede(?:e|s)?(?:\s|$)/.test(normalizeText(status)));
      let status = ownedHere ? 'exclu_deja_possede'
        : readAnywhere ? 'exclu_deja_lu_ou_ecoute'
        : ownedAnywhere ? 'exclu_connu_autre_support'
        : row.souhait ? 'souhait_a_verifier'
        : explicitUnowned ? 'non_possede_renseigne' : 'possession_inconnue';
      checks.set(row, { ownedHere, known: ownedAnywhere || readAnywhere, status });
    }
  }
  return checks;
}

function searchCollection(library, theme, input = {}) {
  const themeSources = theme === 'tous' ? Object.keys(library.sources) : THEMES[theme];
  if (!themeSources) return { statut: 'parametre_invalide', message: 'Thème inconnu.' };
  const search = String(input.recherche ?? '').trim();
  const key = normalizeText(search);
  const state = normalizeText(input.etat || 'tous');
  const support = normalizeText(input.support || 'tous');
  const category = normalizeText(input.categorie || 'tous');
  const statesByTheme = {
    livres: ['tous', 'possedes', 'souhaits', 'non possedes', 'decouvertes', 'non lus', 'lus', 'ecoutes', 'non ecoutes', 'en cours', 'manquants'],
    films: ['tous', 'vus', 'a voir', 'non vus', 'souhaits'],
    series: ['tous', 'a voir', 'non vus', 'en cours', 'a jour', 'souhaits'],
    jeux_video: ['tous', 'possedes', 'souhaits', 'a jouer', 'en cours', 'termines', 'abandonnes', 'coups de coeur'],
    jeux_societe: ['tous', 'possedes', 'souhaits'], tous: ['tous'],
  };
  const validStates = statesByTheme[theme];
  if (!validStates.includes(state)) return { statut: 'parametre_invalide', message: 'État non reconnu. Utilise l’un des états décrits dans l’outil.' };
  const bookSupport = { tous: ['bd', 'roman', 'audio'], bd: ['bd'], roman: ['roman'], romans: ['roman'], audio: ['audio'], audible: ['audio'], livres_audio: ['audio'], 'livres audio': ['audio'], mangas: ['bd'], comics: ['bd'], 'franco belge': ['bd'], autres: ['bd'] };
  if (theme === 'livres' && !bookSupport[support]) return { statut: 'parametre_invalide', message: 'Support : tous, bd, roman, audio, mangas, comics, franco_belge ou autres.' };
  if (theme === 'jeux_societe' && !['tous', 'jeux', 'jeu de base', 'standalone', 'extension', 'extensions', 'accessoire', 'accessoires', 'goodie', 'goodies'].includes(category)) return { statut: 'parametre_invalide', message: 'Catégorie : tous, jeux, jeu_de_base, standalone, extensions, accessoires ou goodies.' };
  if ((search && !key) || key.length > 250) return { statut: 'parametre_invalide', message: 'Recherche avec quelques mots du titre, de l’auteur ou du genre.' };
  let maxDuration = null;
  if (input.duree_max_minutes !== null && input.duree_max_minutes !== undefined && input.duree_max_minutes !== '') {
    maxDuration = Number(String(input.duree_max_minutes).replace(',', '.'));
    if (!Number.isFinite(maxDuration) || maxDuration <= 0) return { statut: 'parametre_invalide', message: 'La durée maximale doit être un nombre positif de minutes.' };
    if (!['livres', 'films'].includes(theme)) return { statut: 'parametre_invalide', message: 'Seuls les films et livres audio ont une durée renseignée dans ces tables.' };
  }
  const selected = theme === 'livres' ? bookSupport[support] : themeSources;
  const unavailable = selected.filter(source => !library.sources[source]?.available);
  if (unavailable.length === selected.length) return { statut: 'indisponible', message: 'Les tables nécessaires ne sont pas disponibles dans cette exécution. Ne conclus pas à une absence.' };
  // Discovery checks also inspect other book supports so a known paper title is not a new audio work.
  const checkedSources = theme === 'livres' && state === 'decouvertes' ? THEMES.livres : selected;
  const partial = checkedSources.some(source => !library.sources[source]?.available || library.sources[source]?.invalidRows);
  const words = key.split(' ').filter(Boolean);
  const isOwned = row => row.possession === true || row.dans_ludotheque === true || row.dans_collection === true;
  const purchaseChecks = theme === 'livres' ? bookPurchaseChecks(library) : null;
  let matches = library.catalog.filter(row => {
    if (!selected.includes(row.support)) return false;
    if (theme === 'livres' && ['mangas', 'comics', 'autres'].includes(support) && row.categorie !== support) return false;
    if (theme === 'livres' && support === 'franco belge' && row.categorie !== 'bd') return false;
    if (theme === 'jeux_societe' && category !== 'tous') {
      if (category === 'jeux' && !row.jeu_complet) return false;
      if (category !== 'jeux' && row.categorie !== category.replace(/s$/, '')) return false;
    }
    if (state === 'possedes' && !isOwned(row)) return false;
    if (state === 'non possedes' && purchaseChecks.get(row).ownedHere) return false;
    if (state === 'decouvertes' && purchaseChecks.get(row).known) return false;
    if (state === 'souhaits' && !row.souhait && !row.a_voir) return false;
    if (state === 'non lus' && !(row.possession && (['non_lu', 'en_cours'].includes(row.lecture) || (row.support === 'audio' && !row.ecoute)))) return false;
    if (state === 'lus' && !(row.lecture === 'lu' || row.ecoute || row.albums_non_possedes_lu > 0)) return false;
    if (state === 'ecoutes' && !row.ecoute) return false;
    if (state === 'non ecoutes' && !(row.support === 'audio' && row.possession && !row.ecoute)) return false;
    if (state === 'manquants' && !(row.support === 'bd' && row.possession && row.albums_manquants > 0)) return false;
    if (state === 'vus' && !row.vu) return false;
    if (['a voir', 'non vus'].includes(state) && !row.a_voir) return false;
    if (state === 'a jour' && !row.a_jour) return false;
    if (state === 'en cours' && !(row.en_cours || row.lecture === 'en_cours' || row.etat_jeu === 'en cours')) return false;
    if (state === 'a jouer' && !(row.dans_ludotheque && row.etat_jeu === 'a jouer')) return false;
    if (state === 'termines' && !(row.dans_ludotheque && row.etat_jeu === 'termine')) return false;
    if (state === 'abandonnes' && !(row.dans_ludotheque && row.etat_jeu === 'abandonne')) return false;
    if (state === 'coups de coeur' && !row.coup_de_coeur) return false;
    if (maxDuration !== null && !(row.duree_minutes > 0 && row.duree_minutes <= maxDuration)) return false;
    return words.every(word => (input.titleOnly ? row.searchTitle : row.searchKey).includes(word));
  });
  const exact = key ? matches.filter(row => row.searchTitle === key) : [];
  if (exact.length) matches = exact;
  const purchaseFilter = theme === 'livres' && ['non possedes', 'decouvertes'].includes(state);
  if (purchaseFilter) {
    // Wish-list entries and explicitly unowned records precede unknown ownership.
    const priority = row => row.souhait ? 0 : purchaseChecks.get(row).status === 'non_possede_renseigne' ? 1 : 2;
    matches.sort((a, b) => priority(a) - priority(b) || a.titre.localeCompare(b.titre, 'fr'));
  }
  const limit = 6;
  const view = row => {
    const { id, searchTitle, searchKey, statuts, ...result } = row;
    if (!result.anomalies.length) delete result.anomalies;
    if (purchaseChecks) result.verification_achat = purchaseChecks.get(row).status;
    return result;
  };
  return { statut: partial ? 'partiel' : 'ok', correspondances: matches.length,
    correspondance_exacte: !!exact.length, resultats_limites: matches.length > limit,
    albums_possedes_correspondants: sumKnown(matches.filter(row => row.support === 'bd'), 'albums_possedes'),
    romans_possedes_correspondants: countIf(matches, row => row.support === 'roman' && row.possession),
    livres_audio_possedes_correspondants: countIf(matches, row => row.support === 'audio' && row.possession),
    resultats: matches.slice(0, limit).map(view),
    remarque: (partial ? 'Sources partielles : aucun total global ni absence certaine. ' : '')
      + (matches.length > limit ? 'Affichage limité à 6 fiches ; les compteurs portent sur toutes les correspondances. Précise la recherche pour les autres résultats. ' : '')
      + (theme === 'livres' ? 'verification_achat : exclu_* interdit une découverte ; souhait_a_verifier indique un souhait, non_possede_renseigne un état explicite et possession_inconnue un état à confirmer. Aucun de ces états ne prouve une absence de lecture non enregistrée. Rapprochement par titre identique normalisé, sans garantie sur les variantes ou homonymes. ' : '')
      + (purchaseFilter ? 'Un filtre vide ne prouve pas l’absence : vérifier chaque titre ciblé avec etat=tous. ' : '')
      + (matches.some(row => row.support === 'bd') ? 'Les numéros des tomes manquants ne figurent pas dans ces données.' : '') };
}

function formatSearchResult(result) {
  if (!['ok', 'partiel'].includes(result.statut)) return result.message;
  if (!result.resultats.length) return result.statut === 'partiel' ? 'Aucun résultat dans les sources disponibles ; certaines tables n’ont pas pu être lues.' : 'Aucun résultat dans les tables pour cette recherche. Essaie un autre mot du titre.';
  return `${result.correspondances} résultat(s) dans les tables${result.correspondance_exacte ? ' pour ce titre exact' : ''}.\n\n`
    + result.resultats.map(row => {
      let text = `• ${row.titre} (${row.support.replace(/_/g, ' ')})`;
      if (row.support === 'bd') text += `\nPossédés : ${formatted(row.albums_possedes)} ; lus enregistrés : ${formatted(row.albums_lus)} ; manquants indiqués : ${formatted(row.albums_manquants)}.`;
      if (row.support === 'roman') text += `\n${row.possession ? 'Possédé' : row.souhait ? 'Liste de souhait' : 'Non enregistré comme possédé'} ; lecture : ${row.lecture.replace(/_/g, ' ')}.`;
      if (row.support === 'audio') text += `\n${row.possession ? 'Possédé' : row.souhait ? 'Liste de souhait' : 'Non enregistré comme possédé'}${row.ecoute ? ', marqué écouté' : ''} ; durée : ${formattedDuration(row.duree_minutes)}.`;
      if (row.support === 'film') text += `\n${row.vu ? 'Vu' : row.a_voir ? 'À voir' : 'Statut inconnu'} ; durée : ${formattedDuration(row.duree_minutes)}.`;
      if (row.support === 'serie') text += `\n${row.a_jour ? 'À jour' : row.en_cours ? 'En cours' : row.a_voir ? 'À voir' : 'Statut inconnu'} ; ${formatted(row.episodes_vus)} épisodes vus, ${formatted(row.episodes_restants)} restants.`;
      if (row.support === 'jeu_video') text += `\n${row.dans_ludotheque ? 'Dans la ludothèque' : row.souhait ? 'Souhait' : 'Statut inconnu'} ; ${row.etat_jeu}.`;
      if (row.support === 'jeu_societe') text += `\n${row.dans_collection ? 'Dans la collection' : row.souhait ? 'Souhait' : 'Statut inconnu'} ; ${row.categorie}.`;
      if (row.anomalies?.length) text += '\nCertaines valeurs sont à vérifier.';
      return text;
    }).join('\n\n') + (result.remarque ? '\n\n' + result.remarque : '');
}

const request = $('Prepare request').first().json;
const parts = $input.all().map(item => item.json);
const catalog = parts.find(item => item.kind === 'catalog');
const music = parts.find(item => item.kind === 'music');
if (!catalog || !music) throw new Error('Both context branches must finish before preparing an answer.');
const library = { catalog: catalog.catalog, sources: catalog.sources, music };
let output = '';
if (request.route === 'stats') {
  const focus = request.focus;
  if (['romans', 'audio', 'bd', 'mangas', 'comics'].includes(focus)) {
    const books = statistics(library, 'livres');
    if (focus === 'romans' && books.romans) output = `Romans : ${books.romans.possedes} titres distincts possédés, ${books.romans.lus} lus, ${books.romans.non_lus} non lus, ${books.romans.en_cours} en cours et ${books.romans.souhaits} en souhait.`;
    else if (focus === 'audio' && books.livres_audio) {
      const audio = books.livres_audio;
      output = `Livres audio : ${audio.possedes} possédés, dont ${audio.ecoutes} marqués écoutés ; ${audio.souhaits} en souhait. Durée renseignée : ${formattedDuration(audio.duree_possedee_connue_minutes)}${audio.titres_duree_inconnue ? ` (${audio.titres_duree_inconnue} titre(s) sans durée connue)` : ''}.`;
    } else if (books.albums && ['bd','mangas','comics'].includes(focus)) output = `${focus === 'bd' ? 'BD franco-belges' : focus === 'mangas' ? 'Mangas' : 'Comics'} : ${formatted(books.albums[focus])} albums enregistrés comme possédés.`;
    else output = formatStatistics(library, 'livres');
  } else output = formatStatistics(library, focus || 'tous');
} else if (request.route === 'tomes') {
  output = formatSearchResult(searchCollection(library, 'livres', { recherche: request.argument, support: 'bd', titleOnly: true }));
} else if (request.route === 'chercher') {
  output = formatSearchResult(searchCollection(library, 'tous', { recherche: request.argument }));
}
return [{ json: { chatInput: request.chatInput, focus: request.focus, library, needsAgent: !output, output } }];

// Shared pure functions, embedded in deterministic branches and bounded AI tools.
const THEMES = {
  livres: ['bd', 'roman', 'audio'], films: ['film'], series: ['serie'],
  jeux_video: ['jeu_video'], jeux_societe: ['jeu_societe'],
};
const normalizeText = value => String(value ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const sumKnown = (rows, field) => rows.some(row => row[field] === null || row[field] === undefined)
  ? null : rows.reduce((sum, row) => sum + row[field], 0);
const countIf = (rows, predicate) => rows.filter(predicate).length;
const formatted = value => value === null || value === undefined ? 'non renseigné' : value.toLocaleString('fr-FR');
const formattedDuration = value => value === null || value === undefined ? 'non renseignée' : `${Math.floor(value / 60)} h ${value % 60} min`;

function statistics(library, theme = 'tous') {
  if (theme === 'musique') return { statut: library.music.statut, fichiers_audio: library.music.total ?? null,
    portee: 'Fichiers identifiés audio directement dans Dossier Musiques ; copies distinctes comptées séparément, sous-dossiers exclus.' };
  const selected = theme === 'tous' ? Object.keys(library.sources) : THEMES[theme];
  if (!selected) return { statut: 'parametre_invalide', message: 'Thème inconnu.' };
  const unavailable = selected.filter(key => !library.sources[key]?.available);
  const invalidRows = selected.reduce((sum, key) => sum + (library.sources[key]?.invalidRows ?? 0), 0);
  const result = { statut: unavailable.length || invalidRows ? 'partiel' : 'ok',
    sources_indisponibles: unavailable, lignes_invalides: invalidRows,
    doublons_regroupes: selected.reduce((sum, key) => sum + (library.sources[key]?.repeatedRows ?? 0), 0) };
  if (theme === 'tous') {
    for (const name of Object.keys(THEMES)) result[name] = statistics(library, name);
    result.musique = statistics(library, 'musique');
    if (Object.keys(THEMES).some(name => result[name].statut !== 'ok') || result.musique.statut !== 'ok') result.statut = 'partiel';
    result.remarque = 'Les thèmes utilisent des unités différentes : aucun total mélangeant livres, films, épisodes et jeux.';
    return result;
  }
  const records = library.catalog.filter(row => selected.includes(row.support));
  if (theme === 'livres') {
    const bd = records.filter(row => row.support === 'bd');
    const ownedBd = bd.filter(row => row.possession === true);
    const badOwned = bd.some(row => row.anomalies.some(text => /albums_possedes|tomes possédés inconnu/.test(text)));
    const albums = {};
    for (const category of ['mangas', 'comics', 'bd', 'autres', 'non_classes']) {
      const unknown = bd.some(row => row.categorie === category && row.anomalies.some(text => /albums_possedes|tomes possédés inconnu/.test(text)));
      albums[category] = unknown ? null : sumKnown(ownedBd.filter(row => row.categorie === category), 'albums_possedes');
    }
    const romans = records.filter(row => row.support === 'roman');
    const audio = records.filter(row => row.support === 'audio');
    const ownedRomans = romans.filter(row => row.possession);
    const ownedAudio = audio.filter(row => row.possession);
    const totalAlbums = badOwned ? null : sumKnown(ownedBd, 'albums_possedes');
    const available = key => library.sources[key]?.available && !library.sources[key].invalidRows;
    result.albums = available('bd') ? { ...albums, total: totalAlbums,
      series_possedees: ownedBd.length, tomes_manquants_series_possedees: sumKnown(ownedBd, 'albums_manquants') } : null;
    result.romans = available('roman') ? { possedes: ownedRomans.length,
      lus: countIf(ownedRomans, row => row.lecture === 'lu'), non_lus: countIf(ownedRomans, row => row.lecture === 'non_lu'),
      en_cours: countIf(ownedRomans, row => row.lecture === 'en_cours'), souhaits: countIf(romans, row => row.souhait) } : null;
    result.livres_audio = available('audio') ? { possedes: ownedAudio.length,
      ecoutes: countIf(ownedAudio, row => row.ecoute), non_marques_ecoutes: countIf(ownedAudio, row => !row.ecoute),
      souhaits: countIf(audio, row => row.souhait), duree_possedee_minutes: sumKnown(ownedAudio, 'duree_minutes'),
      duree_possedee_connue_minutes: ownedAudio.reduce((sum, row) => sum + (row.duree_minutes ?? 0), 0),
      titres_duree_inconnue: countIf(ownedAudio, row => row.duree_minutes === null),
      duree_titres_marques_ecoutes_minutes: sumKnown(ownedAudio.filter(row => row.ecoute), 'duree_minutes') } : null;
    result.total_livres_possedes = result.statut === 'ok' && totalAlbums !== null ? totalAlbums + ownedRomans.length + ownedAudio.length : null;
    if (totalAlbums === null) result.statut = 'partiel';
    result.portee = 'Albums BD + titres distincts Roman + titres audio distincts. Papier et audio sont deux supports séparés. Les éditions portant le même id_unique sont regroupées dans chaque table. La durée écoutée est la durée intégrale des titres marqués écoutés, pas un suivi des écoutes partielles.';
  } else if (theme === 'films') {
    result.films = unavailable.length || invalidRows ? null : { total_references: records.length,
      vus: countIf(records, row => row.vu), a_voir: countIf(records, row => row.a_voir),
      duree_films_vus_minutes: sumKnown(records.filter(row => row.vu), 'duree_minutes'),
      statuts_non_classes: countIf(records, row => !row.vu && !row.a_voir) };
    result.portee = 'Titres distincts dans Trakt ; un film Vu est compté une fois, pas une fois par visionnage. Aucune information de possession DVD.';
  } else if (theme === 'series') {
    const started = records.filter(row => row.en_cours || row.a_jour);
    result.series = unavailable.length || invalidRows ? null : { total_references: records.length,
      a_voir: countIf(records, row => row.a_voir), en_cours: countIf(records, row => row.en_cours),
      a_jour: countIf(records, row => row.a_jour), episodes_vus: sumKnown(records, 'episodes_vus'),
      episodes_restants_series_commencees: sumKnown(started, 'episodes_restants'),
      statuts_non_classes: countIf(records, row => !row.a_voir && !row.en_cours && !row.a_jour) };
    result.portee = 'À jour signifie aucun épisode restant selon la table, pas que la production de la série est terminée. Les épisodes futurs non renseignés ne sont pas connus.';
  } else if (theme === 'jeux_video') {
    const owned = records.filter(row => row.dans_ludotheque);
    result.jeux_video = unavailable.length || invalidRows ? null : { dans_ludotheque: owned.length,
      souhaits: countIf(records, row => row.souhait), termines: countIf(owned, row => row.etat_jeu === 'termine'),
      a_jouer: countIf(owned, row => row.etat_jeu === 'a jouer'), en_cours: countIf(owned, row => row.etat_jeu === 'en cours'),
      abandonnes: countIf(owned, row => row.etat_jeu === 'abandonne'),
      coups_de_coeur: countIf(owned, row => row.coup_de_coeur), completes_100_pourcent: countIf(owned, row => row.complete_100_pourcent) };
    result.portee = 'Jeux distincts par titre. Aucune plateforme, durée de jeu ou fonctionnalité coop n’est présente dans cette table.';
  } else {
    const owned = records.filter(row => row.dans_collection);
    result.jeux_societe = unavailable.length || invalidRows ? null : { articles_collection: owned.length,
      jeux_complets: countIf(owned, row => row.jeu_complet), jeux_de_base: countIf(owned, row => row.categorie === 'jeu de base'),
      standalone: countIf(owned, row => row.categorie === 'standalone'), extensions: countIf(owned, row => row.categorie === 'extension'),
      accessoires: countIf(owned, row => row.categorie === 'accessoire'), goodies: countIf(owned, row => row.categorie === 'goodie'),
      non_classes: countIf(owned, row => !['jeu de base', 'standalone', 'extension', 'accessoire', 'goodie'].includes(row.categorie)),
      souhaits: countIf(records, row => row.souhait),
      valeur_collection_connue_euros: owned.reduce((sum, row) => sum + Math.round((row.prix ?? 0) * 100), 0) / 100,
      prix_inconnus: countIf(owned, row => row.prix === null) };
    result.portee = 'Articles regroupés par nom et catégorie. Jeux complets = jeux de base + standalone, avec les puzzles classés comme jeux de base. Les prix viennent de la table. Nombre de joueurs et durée de partie non renseignés.';
  }
  return result;
}

function formatStatistics(library, theme = 'tous') {
  const stats = statistics(library, theme);
  if (theme === 'tous') return Object.keys(THEMES).map(name => formatStatistics(library, name)).join('\n\n') + '\n\n' + formatStatistics(library, 'musique');
  if (theme === 'musique') return stats.statut === 'ok'
    ? `Musique : ${formatted(stats.fichiers_audio)} fichiers audio directement dans le dossier configuré. Les copies distinctes comptent séparément.`
    : stats.statut === 'non_demande' ? 'Musique : utilise /stats musique pour lancer le comptage complet dans Drive.'
      : 'Musique : le comptage Drive est indisponible. Vérifie le compte et le dossier configurés.';
  const parts = [];
  if (theme === 'livres') {
    parts.push(`Livres — total enregistré comme possédé : ${formatted(stats.total_livres_possedes)}.`);
    if (stats.albums) parts.push(`Mangas : ${formatted(stats.albums.mangas)} ; comics : ${formatted(stats.albums.comics)} ; BD franco-belges : ${formatted(stats.albums.bd)} ; autres : ${formatted(stats.albums.autres)}${stats.albums.non_classes ? ` ; non classés : ${stats.albums.non_classes}` : ''}.`);
    if (stats.romans) parts.push(`Romans : ${stats.romans.possedes} possédés (${stats.romans.lus} lus, ${stats.romans.non_lus} non lus, ${stats.romans.en_cours} en cours) ; ${stats.romans.souhaits} en souhait.`);
    if (stats.livres_audio) parts.push(`Livres audio : ${stats.livres_audio.possedes} possédés, dont ${stats.livres_audio.ecoutes} marqués écoutés ; ${stats.livres_audio.souhaits} en souhait. Durée renseignée : ${formattedDuration(stats.livres_audio.duree_possedee_connue_minutes)}${stats.livres_audio.titres_duree_inconnue ? ` (${stats.livres_audio.titres_duree_inconnue} titre(s) sans durée connue)` : ''}.`);
    parts.push('Papier et audio comptent séparément ; les identifiants répétés sont regroupés dans chaque table.');
  } else if (theme === 'films' && stats.films) {
    parts.push(`Films — ${stats.films.vus} vus ; ${stats.films.a_voir} à voir ; ${stats.films.total_references} références au total.`);
  } else if (theme === 'series' && stats.series) {
    parts.push(`Séries — ${stats.series.en_cours} en cours ; ${stats.series.a_jour} à jour ; ${stats.series.a_voir} à voir.`,
      `Épisodes vus : ${formatted(stats.series.episodes_vus)}. Restants dans les séries commencées : ${formatted(stats.series.episodes_restants_series_commencees)}.`,
      'Une série à jour peut encore avoir de futurs épisodes.');
  } else if (theme === 'jeux_video' && stats.jeux_video) {
    const v = stats.jeux_video;
    parts.push(`Jeux vidéo — ${v.dans_ludotheque} dans la ludothèque ; ${v.souhaits} en souhait.`,
      `${v.termines} terminés ; ${v.a_jouer} à jouer ; ${v.en_cours} en cours ; ${v.abandonnes} abandonnés.`);
  } else if (theme === 'jeux_societe' && stats.jeux_societe) {
    const b = stats.jeux_societe;
    parts.push(`Jeux de société — ${b.jeux_complets} jeux complets (${b.jeux_de_base} jeux de base et ${b.standalone} standalone).`,
      `La collection contient ${b.articles_collection} articles au total, dont ${b.extensions} extensions, ${b.accessoires} accessoires et ${b.goodies} goodies${b.non_classes ? ` ; ${b.non_classes} non classés` : ''}. Souhaits : ${b.souhaits}.`);
  }
  if (stats.statut !== 'ok') parts.push(`Données incomplètes pour ce thème${stats.sources_indisponibles.length ? ` : ${stats.sources_indisponibles.join(', ')}` : ' : certaines lignes ou quantités sont à vérifier'}. Aucun total inconnu n’est remplacé par zéro.`);
  return parts.join('\n');
}

function bookPurchaseChecks(library) {
  // Match identical normalized titles conservatively, without merging record identities or totals.
  const titles = new Map();
  const owned = row => row.possession === true || row.albums_possedes > 0
    || row.statuts.some(status => /^possede(?:e|s)?(?:\s|$)/.test(normalizeText(status)));
  const read = row => row.ecoute === true || ['lu', 'ecoute', 'en_cours'].includes(row.lecture)
    || row.albums_lus > 0 || row.albums_non_possedes_lu > 0
    || row.statuts.some(status => {
      const value = normalizeText(status);
      return !/\bnon lu\b/.test(value) && /\blu\b|\bje lis\b/.test(value);
    });
  for (const row of library.catalog) {
    if (!THEMES.livres.includes(row.support)) continue;
    if (!titles.has(row.searchTitle)) titles.set(row.searchTitle, []);
    titles.get(row.searchTitle).push(row);
  }
  const checks = new Map();
  for (const rows of titles.values()) {
    const ownedAnywhere = rows.some(owned);
    const readAnywhere = rows.some(read);
    for (const row of rows) {
      const sameSupport = rows.filter(other => other.support === row.support);
      const ownedHere = sameSupport.some(owned);
      const explicitUnowned = row.albums_possedes === 0
        || row.statuts.some(status => /^non possede(?:e|s)?(?:\s|$)/.test(normalizeText(status)));
      let status = ownedHere ? 'exclu_deja_possede'
        : readAnywhere ? 'exclu_deja_lu_ou_ecoute'
        : ownedAnywhere ? 'exclu_connu_autre_support'
        : row.souhait ? 'souhait_a_verifier'
        : explicitUnowned ? 'non_possede_renseigne' : 'possession_inconnue';
      checks.set(row, { ownedHere, known: ownedAnywhere || readAnywhere, status });
    }
  }
  return checks;
}

function searchCollection(library, theme, input = {}) {
  const themeSources = theme === 'tous' ? Object.keys(library.sources) : THEMES[theme];
  if (!themeSources) return { statut: 'parametre_invalide', message: 'Thème inconnu.' };
  const search = String(input.recherche ?? '').trim();
  const key = normalizeText(search);
  const state = normalizeText(input.etat || 'tous');
  const support = normalizeText(input.support || 'tous');
  const category = normalizeText(input.categorie || 'tous');
  const statesByTheme = {
    livres: ['tous', 'possedes', 'souhaits', 'non possedes', 'decouvertes', 'non lus', 'lus', 'ecoutes', 'non ecoutes', 'en cours', 'manquants'],
    films: ['tous', 'vus', 'a voir', 'non vus', 'souhaits'],
    series: ['tous', 'a voir', 'non vus', 'en cours', 'a jour', 'souhaits'],
    jeux_video: ['tous', 'possedes', 'souhaits', 'a jouer', 'en cours', 'termines', 'abandonnes', 'coups de coeur'],
    jeux_societe: ['tous', 'possedes', 'souhaits'], tous: ['tous'],
  };
  const validStates = statesByTheme[theme];
  if (!validStates.includes(state)) return { statut: 'parametre_invalide', message: 'État non reconnu. Utilise l’un des états décrits dans l’outil.' };
  const bookSupport = { tous: ['bd', 'roman', 'audio'], bd: ['bd'], roman: ['roman'], romans: ['roman'], audio: ['audio'], audible: ['audio'], livres_audio: ['audio'], 'livres audio': ['audio'], mangas: ['bd'], comics: ['bd'], 'franco belge': ['bd'], autres: ['bd'] };
  if (theme === 'livres' && !bookSupport[support]) return { statut: 'parametre_invalide', message: 'Support : tous, bd, roman, audio, mangas, comics, franco_belge ou autres.' };
  if (theme === 'jeux_societe' && !['tous', 'jeux', 'jeu de base', 'standalone', 'extension', 'extensions', 'accessoire', 'accessoires', 'goodie', 'goodies'].includes(category)) return { statut: 'parametre_invalide', message: 'Catégorie : tous, jeux, jeu_de_base, standalone, extensions, accessoires ou goodies.' };
  if ((search && !key) || key.length > 250) return { statut: 'parametre_invalide', message: 'Recherche avec quelques mots du titre, de l’auteur ou du genre.' };
  let maxDuration = null;
  if (input.duree_max_minutes !== null && input.duree_max_minutes !== undefined && input.duree_max_minutes !== '') {
    maxDuration = Number(String(input.duree_max_minutes).replace(',', '.'));
    if (!Number.isFinite(maxDuration) || maxDuration <= 0) return { statut: 'parametre_invalide', message: 'La durée maximale doit être un nombre positif de minutes.' };
    if (!['livres', 'films'].includes(theme)) return { statut: 'parametre_invalide', message: 'Seuls les films et livres audio ont une durée renseignée dans ces tables.' };
  }
  const selected = theme === 'livres' ? bookSupport[support] : themeSources;
  const unavailable = selected.filter(source => !library.sources[source]?.available);
  if (unavailable.length === selected.length) return { statut: 'indisponible', message: 'Les tables nécessaires ne sont pas disponibles dans cette exécution. Ne conclus pas à une absence.' };
  // Discovery checks also inspect other book supports so a known paper title is not a new audio work.
  const checkedSources = theme === 'livres' && state === 'decouvertes' ? THEMES.livres : selected;
  const partial = checkedSources.some(source => !library.sources[source]?.available || library.sources[source]?.invalidRows);
  const words = key.split(' ').filter(Boolean);
  const isOwned = row => row.possession === true || row.dans_ludotheque === true || row.dans_collection === true;
  const purchaseChecks = theme === 'livres' ? bookPurchaseChecks(library) : null;
  let matches = library.catalog.filter(row => {
    if (!selected.includes(row.support)) return false;
    if (theme === 'livres' && ['mangas', 'comics', 'autres'].includes(support) && row.categorie !== support) return false;
    if (theme === 'livres' && support === 'franco belge' && row.categorie !== 'bd') return false;
    if (theme === 'jeux_societe' && category !== 'tous') {
      if (category === 'jeux' && !row.jeu_complet) return false;
      if (category !== 'jeux' && row.categorie !== category.replace(/s$/, '')) return false;
    }
    if (state === 'possedes' && !isOwned(row)) return false;
    if (state === 'non possedes' && purchaseChecks.get(row).ownedHere) return false;
    if (state === 'decouvertes' && purchaseChecks.get(row).known) return false;
    if (state === 'souhaits' && !row.souhait && !row.a_voir) return false;
    if (state === 'non lus' && !(row.possession && (['non_lu', 'en_cours'].includes(row.lecture) || (row.support === 'audio' && !row.ecoute)))) return false;
    if (state === 'lus' && !(row.lecture === 'lu' || row.ecoute || row.albums_non_possedes_lu > 0)) return false;
    if (state === 'ecoutes' && !row.ecoute) return false;
    if (state === 'non ecoutes' && !(row.support === 'audio' && row.possession && !row.ecoute)) return false;
    if (state === 'manquants' && !(row.support === 'bd' && row.possession && row.albums_manquants > 0)) return false;
    if (state === 'vus' && !row.vu) return false;
    if (['a voir', 'non vus'].includes(state) && !row.a_voir) return false;
    if (state === 'a jour' && !row.a_jour) return false;
    if (state === 'en cours' && !(row.en_cours || row.lecture === 'en_cours' || row.etat_jeu === 'en cours')) return false;
    if (state === 'a jouer' && !(row.dans_ludotheque && row.etat_jeu === 'a jouer')) return false;
    if (state === 'termines' && !(row.dans_ludotheque && row.etat_jeu === 'termine')) return false;
    if (state === 'abandonnes' && !(row.dans_ludotheque && row.etat_jeu === 'abandonne')) return false;
    if (state === 'coups de coeur' && !row.coup_de_coeur) return false;
    if (maxDuration !== null && !(row.duree_minutes > 0 && row.duree_minutes <= maxDuration)) return false;
    return words.every(word => (input.titleOnly ? row.searchTitle : row.searchKey).includes(word));
  });
  const exact = key ? matches.filter(row => row.searchTitle === key) : [];
  if (exact.length) matches = exact;
  const purchaseFilter = theme === 'livres' && ['non possedes', 'decouvertes'].includes(state);
  if (purchaseFilter) {
    // Wish-list entries and explicitly unowned records precede unknown ownership.
    const priority = row => row.souhait ? 0 : purchaseChecks.get(row).status === 'non_possede_renseigne' ? 1 : 2;
    matches.sort((a, b) => priority(a) - priority(b) || a.titre.localeCompare(b.titre, 'fr'));
  }
  const limit = 6;
  const view = row => {
    const { id, searchTitle, searchKey, statuts, ...result } = row;
    if (!result.anomalies.length) delete result.anomalies;
    if (purchaseChecks) result.verification_achat = purchaseChecks.get(row).status;
    return result;
  };
  return { statut: partial ? 'partiel' : 'ok', correspondances: matches.length,
    correspondance_exacte: !!exact.length, resultats_limites: matches.length > limit,
    albums_possedes_correspondants: sumKnown(matches.filter(row => row.support === 'bd'), 'albums_possedes'),
    romans_possedes_correspondants: countIf(matches, row => row.support === 'roman' && row.possession),
    livres_audio_possedes_correspondants: countIf(matches, row => row.support === 'audio' && row.possession),
    resultats: matches.slice(0, limit).map(view),
    remarque: (partial ? 'Sources partielles : aucun total global ni absence certaine. ' : '')
      + (matches.length > limit ? 'Affichage limité à 6 fiches ; les compteurs portent sur toutes les correspondances. Précise la recherche pour les autres résultats. ' : '')
      + (theme === 'livres' ? 'verification_achat : exclu_* interdit une découverte ; souhait_a_verifier indique un souhait, non_possede_renseigne un état explicite et possession_inconnue un état à confirmer. Aucun de ces états ne prouve une absence de lecture non enregistrée. Rapprochement par titre identique normalisé, sans garantie sur les variantes ou homonymes. ' : '')
      + (purchaseFilter ? 'Un filtre vide ne prouve pas l’absence : vérifier chaque titre ciblé avec etat=tous. ' : '')
      + (matches.some(row => row.support === 'bd') ? 'Les numéros des tomes manquants ne figurent pas dans ces données.' : '') };
}

function formatSearchResult(result) {
  if (!['ok', 'partiel'].includes(result.statut)) return result.message;
  if (!result.resultats.length) return result.statut === 'partiel' ? 'Aucun résultat dans les sources disponibles ; certaines tables n’ont pas pu être lues.' : 'Aucun résultat dans les tables pour cette recherche. Essaie un autre mot du titre.';
  return `${result.correspondances} résultat(s) dans les tables${result.correspondance_exacte ? ' pour ce titre exact' : ''}.\n\n`
    + result.resultats.map(row => {
      let text = `• ${row.titre} (${row.support.replace(/_/g, ' ')})`;
      if (row.support === 'bd') text += `\nPossédés : ${formatted(row.albums_possedes)} ; lus enregistrés : ${formatted(row.albums_lus)} ; manquants indiqués : ${formatted(row.albums_manquants)}.`;
      if (row.support === 'roman') text += `\n${row.possession ? 'Possédé' : row.souhait ? 'Liste de souhait' : 'Non enregistré comme possédé'} ; lecture : ${row.lecture.replace(/_/g, ' ')}.`;
      if (row.support === 'audio') text += `\n${row.possession ? 'Possédé' : row.souhait ? 'Liste de souhait' : 'Non enregistré comme possédé'}${row.ecoute ? ', marqué écouté' : ''} ; durée : ${formattedDuration(row.duree_minutes)}.`;
      if (row.support === 'film') text += `\n${row.vu ? 'Vu' : row.a_voir ? 'À voir' : 'Statut inconnu'} ; durée : ${formattedDuration(row.duree_minutes)}.`;
      if (row.support === 'serie') text += `\n${row.a_jour ? 'À jour' : row.en_cours ? 'En cours' : row.a_voir ? 'À voir' : 'Statut inconnu'} ; ${formatted(row.episodes_vus)} épisodes vus, ${formatted(row.episodes_restants)} restants.`;
      if (row.support === 'jeu_video') text += `\n${row.dans_ludotheque ? 'Dans la ludothèque' : row.souhait ? 'Souhait' : 'Statut inconnu'} ; ${row.etat_jeu}.`;
      if (row.support === 'jeu_societe') text += `\n${row.dans_collection ? 'Dans la collection' : row.souhait ? 'Souhait' : 'Statut inconnu'} ; ${row.categorie}.`;
      if (row.anomalies?.length) text += '\nCertaines valeurs sont à vérifier.';
      return text;
    }).join('\n\n') + (result.remarque ? '\n\n' + result.remarque : '');
}

const library = $('Prepare context').first().json.library;
const input = query && typeof query === 'object' ? query : { recherche: String(query ?? '') };
const action = normalizeText(input.action || 'recherche');
if (['statistiques', 'stats', 'compter'].includes(action)) return JSON.stringify(statistics(library, 'livres'));
if (!['recherche', 'chercher'].includes(action)) return JSON.stringify({ statut: 'parametre_invalide', message: 'action doit être recherche ou statistiques.' });
return JSON.stringify(searchCollection(library, 'livres', {
  recherche: input.recherche, etat: input.etat, support: input.support, categorie: input.categorie, duree_max_minutes: input.duree_max_minutes,
}));

